<?php
namespace Tests;
use App\Services\{SalonStore,ProviderPasswords,ProviderIdentity,RecurringBookings,Connections,Notifications};
use Carbon\CarbonImmutable as Time;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{DB,Artisan,Hash,Crypt,Mail,Http};
final class FollowupTest extends TestCase{
 private string $path;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Tesztadatbázis szükséges.');Artisan::call('migrate',['--force'=>true]);foreach(['provider_identities','provider_security','provider_password_tokens','deliveries','calendar_tasks','salon_state','providers'] as $t)DB::table($t)->delete();$s=SalonStore::initial();$s['settings']['providerEmail']='owner@example.com';DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode($s)]);$this->path=storage_path('framework/followup-'.bin2hex(random_bytes(5)));config(['integrations.path'=>$this->path,'operator.connections_path'=>$this->path.'-platform','raero.admin_password_hash'=>Hash::make('Old-password-for-test')]);$this->withSession(['_token'=>str_repeat('f',40)])->withHeader('X-CSRF-TOKEN',str_repeat('f',40));Http::preventStrayRequests();Time::setTestNow('2035-03-01');}
 protected function tearDown():void{foreach(['provider_identities','provider_security','provider_password_tokens'] as $t)DB::table($t)->delete();foreach(glob($this->path.'*') as $p)unlink($p);Time::setTestNow();parent::tearDown();}
 private function booking(array $rule):array{return ['name'=>'Series Guest','phone'=>'06301234567','staff'=>'anna','services'=>['cut'],'start'=>'2035-03-12T09:00:00Z','recurrence'=>$rule];}
 public function test_dates_override_start_and_end_inclusively_and_zero_means_unbounded():void{$this->withSession(['admin'=>true]);$r=$this->postJson('/api/bookings',$this->booking(['frequency'=>'weekly','count'=>0,'startDate'=>'2035-03-13','endDate'=>'2035-03-27']))->assertCreated()->assertJsonPath('seriesCount',3);$this->assertStringStartsWith('2035-03-13', $r->json('start'));$this->postJson('/api/bookings',$this->booking(['frequency'=>'weekly','endDate'=>'2034-01-01']))->assertUnprocessable();}
 public function test_unbounded_series_expands_idempotently_and_stop_prevents_replenishment():void{$this->withSession(['admin'=>true]);$r=$this->postJson('/api/bookings',$this->booking(['frequency'=>'weekly','count'=>0]))->assertCreated();$id=$r->json('seriesId');$n=count(app(SalonStore::class)->read()['bookings']);$this->assertGreaterThan(50,$n);$this->assertLessThan(55,$n);$this->assertSame(0,RecurringBookings::run());Time::setTestNow('2035-06-01');$this->assertGreaterThan(0,RecurringBookings::run());$this->assertSame(0,RecurringBookings::run());$this->postJson('/api/booking-series/'.$id.'/cancel')->assertOk();Time::setTestNow('2035-09-01');$this->assertSame(0,RecurringBookings::run());$this->assertFalse(app(SalonStore::class)->read()['recurringSeries'][$id]['active']);}
 public function test_provider_change_requires_old_password_and_revokes_old_version():void{$this->withSession(['admin'=>true]);$body=['current_password'=>'wrong','password'=>'New-password-for-test','password_confirmation'=>'New-password-for-test'];$this->postJson('/api/provider-password/change',$body)->assertUnprocessable();$body['current_password']='Old-password-for-test';$this->postJson('/api/provider-password/change',$body)->assertOk()->assertSessionHas('provider_password_version',2);$this->assertTrue(Hash::check($body['password'],ProviderPasswords::hash(1)));$this->withSession(['admin'=>true,'provider_password_version'=>1]);$this->getJson('/api/state')->assertUnauthorized();$this->postJson('/api/provider-login',['email'=>'owner@example.com','password'=>$body['password']])->assertOk()->assertSessionHas('admin',true);}
 public function test_provider_reset_is_queued_single_use_expires_and_uses_smtp():void{$this->postJson('/api/provider-password/forgot',['email'=>'unknown@example.com'])->assertOk()->assertExactJson(['ok'=>true]);$this->assertSame(0,DB::table('deliveries')->count());$this->postJson('/api/provider-password/forgot',['email'=>'owner@example.com'])->assertOk();$t=DB::table('provider_password_tokens')->first();$token=Crypt::decryptString($t->payload);$this->assertNotSame($token,$t->token_hash);app(Connections::class)->save(['smtp_host'=>'smtp.example.invalid','smtp_port'=>587,'mail_from'=>'sender@example.com']);Mail::fake();$result=app(Notifications::class)->run();$this->assertSame(1,$result['sent']);Mail::assertSent(\App\Mail\NotificationMail::class,fn($m)=>str_contains($m->contentHtml,$token)&&$m->hasTo('owner@example.com'));$body=['token'=>$token,'password'=>'Reset-password-for-test','password_confirmation'=>'Reset-password-for-test'];$this->postJson('/api/provider-password/reset',$body)->assertOk();$this->postJson('/api/provider-password/reset',$body)->assertUnprocessable();$this->assertTrue(Hash::check($body['password'],ProviderPasswords::hash(1)));}
 public function test_social_identity_does_not_autolink_matching_email_and_registration_is_tenant_scoped():void{$r=$this->app['request'];$r->setLaravelSession($this->app['session.store']);ProviderIdentity::complete($r,'google','new-subject','owner@example.com','Owner','provider',1);$this->assertFalse((bool)session('admin'));$this->assertSame('new-subject',session('provider_social_pending.subject'));$this->getJson('/api/provider-social')->assertOk()->assertJsonMissingPath('subject');$this->postJson('/api/provider-register',['social'=>true,'name'=>'New Studio','city'=>'Adony','category'=>'hair','email'=>'new@example.com'])->assertCreated()->assertSessionHas('admin',true);$id=(int)session('provider_id');$this->assertGreaterThan(1,$id);$this->assertSame($id,(int)DB::table('provider_identities')->where('subject','new-subject')->value('provider_id'));$this->assertSame(4000,json_decode(DB::table('salon_state')->where('id',$id)->value('data'),true)['subscription']['price']);}
 public function test_oauth_provider_mode_uses_identity_instead_of_legacy_allowlist():void{app(Connections::class)->save(['google_client_id'=>'test-id','google_client_secret'=>'test-secret']);Http::fake(['oauth2.googleapis.com/*'=>Http::response(['access_token'=>'test-token']),'openidconnect.googleapis.com/*'=>Http::response(['sub'=>'linked-google','email'=>'owner@example.com','email_verified'=>true,'name'=>'Owner'])]);DB::table('provider_identities')->insert(['provider_id'=>1,'network'=>'google','subject'=>'linked-google','created_at'=>now(),'updated_at'=>now()]);$this->get('/auth/google?mode=provider')->assertRedirect();$state=session('oauth.state');$this->get('/auth/google/callback?state='.$state.'&code=test-code')->assertRedirect('/?provider=1')->assertSessionHas('admin',true)->assertSessionHas('provider_auth_method','social');}
 public function test_later_series_conflict_is_visible_and_does_not_partially_extend():void{$this->withSession(['admin'=>true]);$result=$this->postJson('/api/bookings',$this->booking(['frequency'=>'weekly','count'=>0]))->assertCreated()->json();$s=app(SalonStore::class)->read();$rule=$s['recurringSeries'][$result['seriesId']];$next=RecurringBookings::at($rule['start'],$rule['frequency'],$rule['nextIndex'])->utc()->toISOString();$other=$this->booking([]);unset($other['recurrence']);$other['start']=$next;$this->postJson('/api/bookings',$other)->assertCreated();$n=count(app(SalonStore::class)->read()['bookings']);Time::setTestNow('2035-06-01');$this->assertSame(0,RecurringBookings::run());$s=app(SalonStore::class)->read();$this->assertCount($n,$s['bookings']);$this->assertNotEmpty($s['recurringSeries'][$result['seriesId']]['error']);$this->assertSame($rule['nextIndex'],$s['recurringSeries'][$result['seriesId']]['nextIndex']);}
 public function test_guest_password_change_requires_current_secret_and_revokes_prior_sessions():void{foreach(['guest_auth_tokens','guest_credentials','guest_accounts'] as $t)DB::table($t)->delete();$this->postJson('/api/guest/auth/register',['email'=>'followup@example.com'])->assertCreated();$t=DB::table('guest_auth_tokens')->first();$token=json_decode(Crypt::decryptString($t->payload),true)['token'];$this->postJson('/api/guest/auth/verify',['token'=>$token,'name'=>'Guest','password'=>'Old-guest-password','password_confirmation'=>'Old-guest-password'])->assertOk();$id=session('guest_id');$version=session('guest_password_version');$this->postJson('/api/guest/auth/change',['current_password'=>'wrong','password'=>'New-guest-password','password_confirmation'=>'New-guest-password'])->assertUnprocessable();$this->postJson('/api/guest/auth/change',['current_password'=>'Old-guest-password','password'=>'New-guest-password','password_confirmation'=>'New-guest-password'])->assertOk();$this->withSession(['guest_id'=>$id,'guest_password_account'=>$id,'guest_password_version'=>$version]);$this->getJson('/api/guest')->assertUnauthorized();}
 public function test_expired_provider_reset_and_cross_tenant_link_are_rejected():void{$this->postJson('/api/provider-password/forgot',['email'=>'owner@example.com'])->assertOk();$t=DB::table('provider_password_tokens')->first();DB::table('provider_password_tokens')->update(['expires_at'=>now()->subMinute()]);$this->postJson('/api/provider-password/reset',['token'=>Crypt::decryptString($t->payload),'password'=>'Reset-password-for-test','password_confirmation'=>'Reset-password-for-test'])->assertUnprocessable();$this->assertTrue(Hash::check('Old-password-for-test',ProviderPasswords::hash(1)));app(Connections::class)->save(['google_client_id'=>'test-id','google_client_secret'=>'test-secret']);$this->get('/auth/google?mode=provider-link')->assertForbidden();$this->withSession(['admin'=>true,'provider_id'=>2]);$this->get('/auth/google?mode=provider-link&provider=1')->assertForbidden();}
}
